INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (1, 'corinthians-bate-o-flamengo-e-conquista-o-bicampeonato-supercopa', 'Corinthians bate o Flamengo e conquista o bicampeonato Supercopa', '', '<!-- wp:paragraph -->
<p>O Corinthians venceu o Flamengo por 2 a 0, neste domingo (1), no Estádio Mané Garrincha, e conquistou o bicampeonato Supercopa do Brasil. Os gols do título foram anotados por Gabriel Paulista e Yuri Alberto. O zagueiro marcou ainda no 1º tempo, enquanto o camisa 9 fechou o placar nos acréscimos do 2º tempo.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Expulsão no intervalo</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>O jogo foi marcado por uma expulsão durante o intervalo. No último lance do 1º tempo, Carrascal atingiu o rosto de Breno Bidon, mas o árbitro Rafael Klein mandou os jogadores para os vestiários e revisou no VAR apenas no retorno para o 2º tempo, aplicando o vermelho antes de recomeçar a partida.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Estreia de Paquetá</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Paquetá reestreou pelo Flamengo. O camisa 20 começou no banco de reservas e foi acionado aos 12 minutos do 2ª tempo, no lugar de Pedro. Ele teve uma chance clara para empatar já nos acréscimos, mas mandou por cima do gol.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading"><strong>Lista de campeões atualizada!</strong></h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Com o título, o Corinthians conquistou o bicampeonato da Supercopa do Brasil. O Flamengo é o maior campeão do torneio, com três taças. Veja a lista abaixo:</p>
<!-- /wp:paragraph -->

<!-- wp:list -->
<ul class="wp-block-list"><!-- wp:list-item -->
<li>Flamengo - 3 títulos</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li><strong>Corinthians - 2 títulos</strong></li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Grêmio - 1 título</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Atlético-MG - 1 título</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Palmeiras - 1 título</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>São Paulo - 1 título</li>
<!-- /wp:list-item --></ul>
<!-- /wp:list -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Gols</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>1 a 0 - Depay cobrou escanteio curto, e a bola foi recuada até Matheuzinho na intermediária. O lateral corintiano levantou na área, Gustavo Henrique ganhou de Varela pelo alto e escorou de cabeça para Gabriel Paulista chegar batendo e balançar as redes</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>2 a 0 - Yuri Alberto foi lançado na frente e fez por cima de Rossi. O VAR ainda revisou o lance e validou o gol.</p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-01 20:52:02', '2026-02-01 20:52:02', '2026-02-01 20:52:02', 1, 1, 3);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (2, 'chumbinho-becker-lenda-do-motocross-no-brasil-morre-em-santa-catarina', '''Chumbinho'' Becker, lenda do motocross no Brasil, morre em Santa Catarina', '', '<!-- wp:paragraph -->
<p>Milton “Chumbinho” Becker, uma lenda do motocross e campeão brasileiro na modalidade 27 vezes, morreu aos 56 anos em um acidente na Rodovia SC-305, em Campo Erê, no Oeste de Santa Catarina, na tarde de sábado (31).</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O Corpo de Bombeiros detalhou que o Chumbinho Becker estava em uma moto Yamaha MT‑09 Tracker que saiu da pista e caiu em uma ribanceira ao lado de uma ponte. Ao chegar no local, os socorristas o encontraram sem vida.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A morte foi confirmada nas redes sociais pelo irmão Elton Becker, também ex-piloto profissional e campeão de motocross. A cerimônia de despedida acontece iniciou às 13h deste domingo (1º) no Complexo Oktoberfest da cidade vizinha de Itapiranga.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A Confederação Brasileira de Motociclismo (CBM) publicou nota na manhã deste domingo (1°) lamentando a morte de Chumbinho Becker, destacando a trajetória e o referendando como "um dos maiores ícones da história do esporte sobre duas rodas no Brasil".</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>"Chumbinho foi um piloto extraordinário, cuja trajetória se confunde com a própria evolução do motocross nacional. Dono de um currículo repleto de títulos brasileiros e internacionais, ele se destacou não apenas pela velocidade, mas pela longevidade e pelo profissionalismo que serviram de exemplo para diversas gerações de atletas", diz a nota.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><em>Da Redação</em><br></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-01 20:59:48', '2026-02-01 20:59:48', '2026-02-01 20:59:48', 1, 1, 4);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (3, 'alcaraz-vence-djokovic-e-e-campeao-do-australian-open', 'Alcaraz vence Djokovic e é campeão do Australian Open', '', '<!-- wp:paragraph -->
<p><br>O espanhol Carlos Alcaraz, no começo da manhã deste domingo (1º), se tornou o homem mais jovem a completar o Grand Slam, adicionando o título do Australian Open à coleção de troféus após derrotar o sérvio Novak Djokovic em uma emocionante final.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Apesar de perder o primeiro set para um Djokovic implacável, totalmente focado em conquistar o 25º título de Major, um recorde, Alcaraz reagiu e venceu por 3 a 1 (2-6, 6-2, 6-3 e 7-5), confirmando a posição como número 1 do mundo.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Seria uma tarefa monumental para Djokovic, que tinha dez títulos em dez finais em Melbourne, derrotar um adversário mais jovem, especialmente depois de ter se esforçado tanto para vencer o número 2 do mundo, Jannik Sinner, em uma semifinal de cinco sets na sexta-feira (30).</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Mas, aos 38 anos, e diante do domínio contínuo de Sinner e Alcaraz, restam cada vez menos oportunidades para o sérvio conquistar o tão desejado 25º título, que o colocaria à frente de Margaret Court e o tornaria o tenista mais premiado da história.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>E, em Alcaraz, enfrentava um adversário capaz de devolver quase todos os golpes, cujo atletismo permite ao espanhol prolongar os ralis além do que parece humanamente possível, e cuja criatividade pode surpreender até mesmo alguém tão experiente quanto Djokovic.</p>
<!-- /wp:paragraph -->

<!-- wp:image {"id":387628,"sizeSlug":"full","linkDestination":"none"} -->
<figure class="wp-block-image size-full"><img src="https://diario.dopovo.com.br/wp-content/uploads/2026/02/Carlos-Alcaraz2.webp" alt="" class="wp-image-387628"/><figcaption class="wp-element-caption">Carlos Alcaraz com o troféu de campeão do Australian Open - Foto: Rede social</figcaption></figure>
<!-- /wp:image -->

<!-- wp:paragraph -->
<p>Com apenas 22 anos, Alcaraz agora se junta a um clube exclusivo composto por apenas outros cinco homens que venceram os quatro torneios do Grand Slam de tênis – o Australian Open, Roland Garros, Wimbledon e US Open – na Era Aberta.<br><br><br><em>Com informações da Reuters</em><br></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-01 21:09:49', '2026-02-01 21:09:49', '2026-02-01 21:09:49', 1, 1, 9);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (4, 'tce-pi-mostra-fragilidades-na-gestao-tributaria-dos-municipios', 'TCE-PI mostra fragilidades na gestão tributária dos municípios', '', '<!-- wp:paragraph -->
<p>O Tribunal de Contas do Estado do Piauí (TCE-PI), por meio da Diretoria de Fiscalização de Gestão e Contas Públicas (DFContas), divulgou na última quinta-feira (29), durante a primeira Sessão Plenária de 2026, um levantamento que aponta fragilidades estruturais e operacionais na gestão tributária municipal, exercícios de 2023 e de 2024, com impactos diretos sobre a arrecadação própria e a autonomia financeira dos entes locais, mantendo padrões semelhantes aos verificados nos exercícios de 2020 e 2021. </p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Veja os pontos complementares do relatório aprovado pela Corte:</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Arrecadação e autonomia financeira</h3>
<!-- /wp:heading -->

<!-- wp:list -->
<ul class="wp-block-list"><!-- wp:list-item -->
<li><strong>Desempenho do IPTU:</strong> Foi o único tributo a apresentar <strong>queda (2%)</strong> em relação ao exercício anterior, evidenciando falhas na atualização de plantas genéricas de valores e na cobrança efetiva TCE-PI .</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li><strong>Dependência Externa:</strong> A receita própria representa, em média, apenas <strong>4% da receita corrente total</strong> dos municípios piauienses, mantendo uma dependência severa de repasses como FPM e ICMS <a href="https://www.tcepi.tc.br/" target="_blank" rel="noreferrer noopener">TCE-PI - Relatórios</a>.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li><strong>Taxa de Lixo (TSMRSU):</strong> Embora obrigatória pelo Marco Legal do Saneamento, apenas <strong>17 municípios</strong> realizam a cobrança efetiva, o que pode configurar renúncia de receita. </li>
<!-- /wp:list-item --></ul>
<!-- /wp:list -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Fragilidades operacionais</h3>
<!-- /wp:heading -->

<!-- wp:list -->
<ul class="wp-block-list"><!-- wp:list-item -->
<li><strong>Tecnologia e Dados:</strong> O levantamento aponta a falta de sistemas informatizados integrados e a ausência de cruzamento de dados com órgãos federais e estaduais para combater a evasão fiscal.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li><strong>Dívida Ativa:</strong> Grande parte dos municípios não possui procedimentos céleres de cobrança administrativa ou judicial, resultando em altos índices de prescrição de débitos.</li>
<!-- /wp:list-item --></ul>
<!-- /wp:list -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Determinações da Corte</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Sob relatoria do&nbsp;<strong>conselheiro substituto Jackson Veras</strong>, o Tribunal determinou que os gestores:</p>
<!-- /wp:paragraph -->

<!-- wp:list {"ordered":true} -->
<ol class="wp-block-list"><!-- wp:list-item -->
<li>Promovam a <strong>criação de cargos efetivos</strong> para a carreira de Auditor Fiscal por meio de concurso público.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Implementem ou atualizem o <strong>Código Tributário Municipal</strong>.</li>
<!-- /wp:list-item -->

<!-- wp:list-item -->
<li>Regularizem a cobrança da <strong>Taxa de Manejo de Resíduos Sólidos</strong> para evitar sanções fiscais.</li>
<!-- /wp:list-item --></ol>
<!-- /wp:list -->

<!-- wp:paragraph -->
<p><em>Da Redação<br></em></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-01 21:28:38', '2026-02-01 21:28:38', '2026-02-01 21:28:38', 1, 1, 6);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (5, 'caetano-veloso-e-maria-bethania-vencem-grammy-de-melhor-album-global', 'Caetano Veloso e Maria Bethânia vencem Grammy de Melhor Álbum Global', 'Premiação', '<!-- wp:paragraph -->
<p>Caetano Veloso e Maria Bethânia conquistaram neste domingo (1) o troféu de melhor álbum de música global no Grammy 2026, desbancando trabalhos do indiano Sidhant Bhatia, o nigeriano Burna Boy, o senegalense Youssou N’Dour, a banda Shakti e a britânica-indiana Anoushka Shankar.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Este é o terceiro Grammy de Caetano e o primeiro de Bethânia. Nenhum deles, porém, estava presente para aceitar a estatueta.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Registro da turnê encabeçada por ambos entre 2024 e 2025, Caetano e Bethânia Ao Vivo está disponível mas plataformas de streaming.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A categoria foi anunciada ainda durante a Premiere Ceremony, transmitida no canal de YouTube da Academia.<br><br></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-01 21:38:02', '2026-02-01 21:38:02', '2026-02-01 21:38:02', 1, 1, 7);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (6, 'abertura-do-ano-legislativo-acontece-nesta-segunda-feira', 'Abertura do Ano Legislativo acontece nesta segunda-feira', '', '<!-- wp:paragraph -->
<p>A Assembleia Legislativa do Piauí (Alepi) realiza, na segunda-feira (2), sessão especial de instalação da 4ª Sessão Legislativa da 20ª Legislatura. A abertura do Ano Legislativo acontecerá no Plenário Waldemar Macedo, a partir das 10 horas, com a leitura da Mensagem do governador, Rafael Fonteles (PT) e a entrega de parte da reforma do Palácio Petrônio Portella, sede do Legislativo.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><br>“Esse bloco da presidência, Diretoria de Comunicação, Secretaria, serão entregues agora. No dia 20, nós já teremos mais uma etapa concluída. Temos um cronograma de entrega dos gabinetes parlamentares até o final do mês de março. Queremos entregar quanto antes, para devolver a vida à Assembleia, para podermos receber a população dia após dia”, anunciou o presidente da Alepi, deputado Severo Eulálio (MDB).</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Comissões</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p><br>Na terça-feira (3), o presidente Severo planeja discutir com os deputados a formação das comissões permanentes, especialmente da Comissão de Constituição e Justiça (CCJ). “É nas comissões que os projetos são discutidos, onde cada um é esmiuçado. Analisa-se a constitucionalidade, a admissibilidade, o mérito de cada matéria, tanto de iniciativa parlamentar quanto dos demais poderes”, afirma.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Desafios</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p><br>Severo adiantou que, por ser ano eleitoral, os parlamentares precisarão enfrentar o desafio de continuar os trabalhos institucionais e as agendas de campanha. Por esta razão, as sessões das segundas e quintas-feiras devem ser híbridas, com votações e discussões sendo realizadas de forma presencial e remota, ao mesmo tempo. As sessões das terças e quartas-feiras serão presenciais.</p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-01 22:09:46', '2026-02-01 22:09:46', '2026-02-01 22:09:46', 1, 1, 1);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (7, 'criminosos-encapuzados-invadem-residencia-e-matam-homem-a-tiros-em-luis-correia', 'Criminosos encapuzados invadem residência e matam homem a tiros em Luis Correia', 'Crime', '<!-- wp:paragraph -->
<p><br>Três homens encapuzado mataram na noite de domingo (1) em Luis Correia, no norte de estado, um homem identificado por Israel da Silva Pinheiro, o "Nego". Os criminosos invadiram a residência da vítima e o executaram a tiros.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>De acordo com informações de major Bernardo, comandante do 24º Batalhão de Polícia Militar, os criminosos invadiram a residência e renderam a família e isolaram a vítima antes dos disparos.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A área foi isolada pelo 24º Batalhão de Polícia Militar e a perícia foi realizada pela Polícia Civil. Uma equipe do Instituto de Medicina Legal (IML) fez a remoção do corpo.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O caso está agora sob responsabilidade da Delegacia de Luís Correia, que busca identificar os autores e a motivação do homicídio.<br><br></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 09:05:59', '2026-02-02 09:05:59', '2026-02-02 09:05:59', 1, 1, 2);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (8, 'colisao-entre-van-e-picape-deixa-tres-pessoas-mortas-no-sul-do-piaui', 'Colisão entre Van e Picape deixa três pessoas mortas no Sul do Piauí', 'BR-135', '<!-- wp:paragraph -->
<p>Uma colisão envolvendo uma picape e uma van neste domingo deixou três pessoas mortas na BR-135 acidente na BR-135, no trecho entre Canto do Buriti e Eliseu Martins, no Sul do Piauí. A vítimas foram identificadas por Domingas Miranda dos Santos (servidora de Palmeira do Piauí), Felipe Luz da Silva e Halef Magalhães dos Santos.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>De acordo com informações preliminares, a Picape tentou ultrapassar uma moto e colidiu frontalmente com uma Van que vinha no sentido oposto com 16 pessoas.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O Serviço de Atendimento Móvel de Urgência (SAMU) e o Corpo de Bombeiros atuaram no resgate, levando os feridos para o Hospital Regional de Canto do Buriti.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A Prefeitura de Palmeira do Piauí emitiu nota de pesar lamentando as mortes e solidarizou-se com os familiares e amigos das vítimas.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Nota de pesar:</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Com pesar, comunicamos o falecimento de três palmeirinos vítimas de um trágico acidente.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A Prefeitura Municipal de Palmeira do Piauí manifesta profundo pesar pelo trágico acidente ocorrido, que resultou no falecimento de três palmeirinos: Domingas Miranda dos Santos, servidora de nosso município, Felipe Luz da Silva e Halef Magalhães dos Santos</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Neste momento de imensa dor e consternação, nos solidarizamos com os familiares, amigos e colegas de trabalho, expressando nossas mais sinceras condolências. Que Deus conceda força, conforto e serenidade a todos para enfrentar essa irreparável perda.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A administração municipal se une em luto e oração, desejando que as vítimas descansem em paz. <br><br></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 09:34:51', '2026-02-02 09:34:51', '2026-02-02 09:34:51', 1, 1, 10);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (9, 'mulher-morre-em-desabamento-de-imoveis-no-maracana-oito-pessoas-foram-resgatadas', 'Mulher morre em desabamento de imóveis no Maracanã; oito pessoas foram resgatadas', 'Rio de Janeiro', '<!-- wp:paragraph -->
<p>Quatro imóveis vieram abaixo na madrugada desta segunda-feira (2) no bairro Maracanã, na zona norte do Rio de Janeiro. O desabamento ocorreu na Avenida Presidente Castelo Branco, pouco depois da 1h30, mobilizando uma grande operação de resgate.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Equipes do Corpo de Bombeiros foram acionadas imediatamente após o colapso das estruturas. Até o momento, oito pessoas foram retiradas com vida dos escombros. Uma das vítimas precisou ser levada para o Hospital Municipal Salgado Filho para atendimento médico.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>As buscas continuam porque duas pessoas ainda não haviam sido localizadas até a última atualização. Entre as vítimas encontradas, uma criança foi resgatada com vida, enquanto uma mulher não resistiu e teve a morte confirmada no local.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A operação envolve mais de 50 bombeiros, além de sete unidades especializadas, incluindo equipes do Grupo de Operações Especiais e profissionais em formação no Curso de Operações de Salvamento em Desastres. Ao todo, 12 viaturas dão suporte aos trabalhos.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>As causas do desabamento ainda serão apuradas. A área permanece isolada enquanto as equipes seguem atuando na busca por possíveis sobreviventes e na avaliação dos riscos estruturais.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 10:05:03', '2026-02-02 10:05:03', '2026-02-02 10:05:03', 1, 1, 11);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (10, 'governador-rafael-fonteles-faz-abertura-do-ano-legislativo-na-alepi-acompanhe-ao-vivo', 'Governador Rafael Fonteles faz abertura do ano legislativo na Alepi; acompanhe', 'Mensagem', '<!-- wp:paragraph -->
<p>O governador do Piauí, Rafael Fonteles (PT) fez nesta segunda-feira (2) a abertura oficial do ano legislativo na Assembleia Legislativa do Estado (Alepi). O gestor apresenta um balanço das ações desenvolvidas ao longo dos três primeiros anos de governo, além de detalhar as prioridades e metas previstas para 2026.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Confira a mensagem abaixo</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p><em><a href="https://www.al.pi.leg.br/comunicacao/tv-assembleia/">TV Assembleia — Assembleia Legislativa do Piauí</a></em></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 11:18:12', '2026-02-02 11:18:12', '2026-02-02 11:18:12', 1, 1, 12);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (11, 'deputado-severo-eulalio-destaca-avancos-na-abertura-do-ano-legislativo', 'Deputado Severo Eulálio destaca avanços na abertura do ano legislativo', 'Alepi', '<!-- wp:paragraph -->
<p>O presidente da Assembleia Legislativa do Piauí, deputado Severo Eulálio (MDB), destacou nesta segunda-feira (2) na abertura do ano avanços na expansão&nbsp; do sinal da TV Assembleia para Picos, Parnaíba e Floriano. O parlamentar também afirmou que democracia se fortalece por meio do legislativo.&nbsp;</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><br>“Inaugurar mais um ano de trabalhos parlamentares é sempre motivo de entusiasmo. Fazê-lo em 2026, ano de eleições gerais, confere a esse momento uma dimensão ainda mais significativa. É neste Parlamento que se fortalece a democracia. É por meio do debate legislativo que se pavimentam os caminhos para o futuro e é com o espírito construtivo que iniciamos esta jornada. Ao inaugurar essa nova sessão legislativa, carregamos a certeza de que a democracia se fortalece pelo trabalho contínuo, pelo diálogo permanente e pela dedicação diuturna ao interesse público. É nesse espírito que nos reunimos hoje, prontos para enfrentar os desafios e abraçar as oportunidades que 2026 nos reserva”, disse</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Severo aproveitou a oportunidade para prestar contas do primeiro ano de sua gestão à frente da Casa, marcado pela implantação do Programa Avança Alepi; pela expansão do sinal da TV Assembleia para Picos, Parnaíba e Floriano; e pela instalação da sede do Legislativo nos municípios de Picos, Oeiras, Esperantina, São Raimundo Nonato, Parnaíba, Floriano, Pedro II e Bom Jesus, além de Teresina, em razão das comemorações pelos 190 anos do Legislativo piauiense.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O emedebista destacou a prestação de serviços diretos à população, contabilizando quase 7 mil atendimentos por meio do projeto Assembleia em Ação, mais de 6 mil atendimentos pelo Procon Alepi, mais de mil atendimentos em três meses pelo programa Bem-Estar Alepi, e mais de 1.500 inscrições nos cursos de capacitação da Escola do Legislativo no interior.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Outras inovações citadas foram o lançamento do Prêmio de Comunicação “Pires de Sabóia” e da 1ª Corrida Alepi, bem como a conquista do Selo Ouro em Transparência Pública, concedido pela Associação dos Membros dos Tribunais de Contas do Brasil (Atricon).</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“Alcançamos 100% dos critérios essenciais, um reconhecimento inédito para esta Casa. Este selo não é apenas uma distinção honorífica, é a comprovação material do nosso compromisso irredutível com a transparência e com o interesse público”, pontuou.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><br>O presidente também ressaltou o maior quantitativo de matérias aprovadas pela Comissão de Constituição e Justiça (CCJ) nos últimos cinco anos, alcançando 630 matérias em mais de 30 reuniões. O Plenário, por sua vez, aprovou 957 projetos de lei, indicativos, propostas de emendas constitucionais e outros atos.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><br>“Esta Casa cumpriu muito bem seu papel e eu agradeço imensamente pela parceria, seja da base aliada, seja da oposição. Os deputados da oposição, quando fazem as críticas, também ajudam o governo a errar menos e a acertar mais”, disse o governador Rafael Fonteles (PT), que parabenizou os parlamentares e desejou que este ano seja ainda mais exitoso, especialmente em razão da conclusão da reforma do Palácio Petrônio Portella, sede do Legislativo, prevista para o final do mês de março.<br><br><em>Com informações da Alepi</em><br></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 13:28:05', '2026-02-02 13:28:05', '2026-02-02 13:28:05', 1, 1, 13);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (12, 'governo-libera-mais-r-39-bi-para-pagar-saque-aniversario-do-fgts', 'Governo libera mais R$ 3,9 bi para pagar saque-aniversário do FGTS', '', '<!-- wp:paragraph -->
<p>O governo federal libera, a partir desta segunda-feira (2), R$ 3,9 bilhões para pagamento da segunda parcela a trabalhadores que optaram pelo saque-aniversário do Fundo de Garantia do Tempo de Serviço (FGTS).</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O valor corresponde aos recursos retidos de trabalhadores que foram demitidos entre janeiro de 2020 e 20 de dezembro de 2025. De acordo com o Ministério do Trabalho e Emprego, o pagamento desses saldos remanescentes nesta segunda etapa beneficiará 822,6 mil pessoas.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Os pagamentos dos saldos remanescentes serão feitos até o dia 12 de fevereiro.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Na primeira etapa, foram liberados também R$ 3,8 bilhões, que beneficiaram mais de 14 milhões de pessoas, conforme previsto em medida provisória publicada no dia 23 de dezembro.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>&gt;&gt; Siga o canal da Agência Brasil no WhatsApp</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Penalização injusta</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Em nota, o MTE lembra que a modalidade impõe uma “penalização injusta” aos trabalhadores e trabalhadoras que optam por esse formato, ao impedir o acesso aos recursos do FGTS em caso de demissão.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“O saque-aniversário tem essa crueldade com o trabalhador e com a trabalhadora, que adere à modalidade e fica impedido de acessar o saldo quando perde o emprego”, alerta o ministro Luiz Marinho ao lembrar que o FGTS é uma “poupança individual criada para amparar o trabalhador e a trabalhadora nos momentos de desemprego, mas, na prática, ele não consegue acessá-la justamente quando mais precisa”.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>De acordo com o MTE, a maior parte dos trabalhadores terá os valores creditados automaticamente nas contas bancárias previamente cadastradas no aplicativo FGTS.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Quem não informou um número de conta para o depósito poderá fazer o saque por meio dos terminais de autoatendimento da Caixa; nas casas lotéricas; ou nas unidades do CAIXA Aqui.</p>
<!-- /wp:paragraph -->

<!-- wp:heading -->
<h2 class="wp-block-heading">Empréstimos bancários</h2>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Dos 14,1 milhões de pessoas com saldo disponível para saque, 9,9 milhões possuem parte dos recursos parcialmente comprometidos com empréstimos bancários, “o que impede o recebimento do valor integral”, alerta o ministério.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“Outras 2,1 milhões de pessoas têm o saldo totalmente comprometido, não havendo, portanto, valores disponíveis para saque”, acrescentou.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O MTE informa que, desde 2020, cerca de R$ 197 bilhões já foram liberados pela modalidade saque-aniversário.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Desse total, 40% foram destinados diretamente aos trabalhadores, enquanto 60% foram transferidos aos bancos que anteciparam os valores por meio de operações de crédito, detalha o ministério.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Segundo a pasta, atualmente 40,3 milhões de pessoas aderiram à modalidade saque-aniversário, em um total de 130 milhões de trabalhadores celetistas. Deste total, 28,5 milhões possuem operações de antecipação de valores ativas.<br><br></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 13:37:59', '2026-02-02 13:37:59', '2026-02-02 13:37:59', 1, 1, 23);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (13, 'justica-condena-homem-a-22-anos-de-prisao-por-matar-a-esposa', 'Justiça condena homem a 22 anos de prisão por matar a esposa', 'Feminicídio', '<!-- wp:paragraph -->
<p>O Tribunal do Júri de Esperantina condenou na última sexta-feira (30) Agripino Gomes a 22 anos e 6 meses de reclusão, em regime inicial fechado, pela prática de homicídio qualificado contra Maria Mercês dos Reis. O MPPI foi representado pelo Promotor de Justiça Antenor Filgueiras Lobo Neto.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>De acordo com a denúncia, o réu desferiu diversos golpes de faca contra a vítima, que era sua esposa, no dia 10 de julho de 2014, na localidade Angelim, zona rural do município.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Nos debates, o Ministério Público sustentou a condenação por homicídio qualificado por motivo torpe e mediante recurso que dificultou a defesa da vítima. A defesa buscou afastar as qualificadoras. Os jurados reconheceram a materialidade do crime, a autoria e as duas qualificadoras, além de rejeitarem o pedido de absolvição.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A sentença fixou a pena definitiva em 22 anos e 6 meses de reclusão, considerando agravantes como violência contra a mulher, meio cruel e recurso que dificultou a defesa da vítima. O juiz determinou que o réu permaneça preso para início do cumprimento da pena.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 13:51:11', '2026-02-02 13:51:11', '2026-02-02 13:51:11', 1, 1, 21);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (14, 'fachin-anuncia-carmen-lucia-como-relatora-de-codigo-de-etica-do-stf', 'Fachin anuncia Cármen Lúcia como relatora de Código de Ética do STF', 'Ano Judiciário', '<!-- wp:paragraph -->
<p>O presidente do Supremo Tribunal Federal (STF), Edson Fachin, anunciou nesta segunda-feira (2) que a ministra Cámen Lúcia será relatora da proposta de criação de um código de ética para os integrantes da Corte.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Fachin discursou durante a sessão solene de abertura do Ano Judiciário de 2026, cerimônia que marca a abertura dos trabalhos após o período de recesso. O ministro disse que as instituições têm desafios para se manterem íntegras e com legitimidade.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>"Momentos de adversidade exigem mais do que discurso, pedem responsabilidade institucional, clareza de limites e fidelidade absoluta à Constituição da República."</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O presidente do STF afirmou que os ministros "respondem pelas escolhas que fazem" e que o é momento é de "autocorreção".</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Diante da resistência interna de ministros que são contra a aprovação de regras para regular a conduta da Corte, Fachin prometeu que buscará o diálogo com os colegas pela aprovação do texto.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>"Vamos caminhar juntos na construção do consenso no âmbito desse colegiado. Impende dialogar e construir confiança pública, porque nessa reside a verdadeira força do Estado Democrático de Direito", afirmou durante a solenidade.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A cerimônia foi acompanhada pelo presidente Luiz Inácio Lula da Silva, os presidentes da Câmara dos Deputados, Hugo Motta (Republicanos-PB), e do Senado, Davi Alcolumbre (União-AP), além de outras autoridades.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Banco Master</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p><br>O anúncio sobre a criação de um código de ética para o STF ocorre após membros da Corte serem criticados publicamente pela condução das investigações envolvendo as fraudes no Banco Master.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>No mês passado, o ministro Alexandre de Moraes negou ter participado de um encontro com o ex-presidente do Banco Regional de Brasília (BRB) Paulo Henrique Costa, no primeiro semestre de 2025, na casa do banqueiro Daniel Vorcaro, dono do Banco Master.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O suposto encontro foi noticiado pelo Portal Metrópoles e teria ocorrido em meio ao processo de tentativa de compra do Master pelo BRB. Em nota à imprensa, Moraes classificou a reportagem como “falsa e mentirosa”.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Antes da liquidação do Master pelo Banco Central, o escritório de advocacia Barci de Moraes, que pertence à família do ministro, prestou serviços ao banco de Vorcaro.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>No início deste mês, o ministro Dias Toffoli passou a ser criticado por permanecer na condição de relator do caso após matérias jornalísticas informarem que a Polícia Federal encontrou irregularidades em um fundo de investimento ligado ao Banco Master. O fundo comprou uma participação no resort Tayayá, localizado no Paraná, que era de propriedade de familiares do ministro.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Fachin também foi criticado por divulgar uma nota à imprensa para defender a atuação de Toffoli.</p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 19:31:26', '2026-02-02 19:31:26', '2026-02-02 19:31:26', 1, 1, 17);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (15, 'hugo-motta-destaca-prioridades-legislativas-na-abertura-do-ano-legislativo-da-camara', 'Hugo Motta destaca prioridades legislativas na abertura do ano legislativo da Câmara', '', '<!-- wp:paragraph -->
<p>O presidente da Câmara dos Deputados, Hugo Motta (Republicanos-PB), afirmou que 2026 será marcado por responsabilidade, espírito público e compromisso com a democracia. A declaração foi feita na abertura do ano legislativo do Congresso Nacional nesta segunda-feira (2).</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“É um orgulho e uma responsabilidade presidir a Câmara dos Deputados no ano de seu bicentenário. Essa celebração que reafirma seu papel essencial na construção de um Brasil mais justo, participativo e soberano”, disse Motta em seu discurso.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O presidente da Câmara destacou a aprovação, em 2025, da reforma do Imposto de Renda, a conclusão da reforma tributária e a votação da proteção de crianças e adolescentes em ambiente digital (ECA Digital), entre outras propostas.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Segundo Motta, neste ano a Câmara deve manter o foco em entregas à população, com votações de interesse nacional. Ele também defendeu um plenário soberano e independente e a prerrogativa constitucional das emendas parlamentares, destinadas a atender demandas em diferentes regiões do país.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“Cabe a este plenário, soberano e independente, perseguir esse caminho dia e noite, com votações de propostas de interesse do país. E fazer valer a prerrogativa constitucional do Congresso de destinar as emendas parlamentares aos rincões Brasil afora, que, na maioria das vezes, não estão aos olhos do Poder Público”, defendeu o presidente.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Votações</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p><br>Motta confirmou ainda a votação, hoje, da  MP Gás do Povo e, após o Carnaval, a votação da  PEC da Segurança Pública. Motta também quer dar início às discussões do fim da escala de trabalho 6x1, e aos debates sobre incentivos aos Serviços de Datacenter.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Outros temas a serem debatidos pela Câmara, segundo o presidente, são: Inteligência Artificial; combate ao feminicídio; e o acordo União Europeia-Mercosul.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“Da mesma forma, vamos aprofundar as discussões sobre a relação entre trabalhadores de aplicativos e plataformas digitais, buscando conciliar produtividade, direitos e desenvolvimento. Essa tarefa é indispensável para preparar o Brasil para uma nova economia baseada em tecnologia, em inovação e em investimentos sustentáveis”, disse.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><em>Fonte: Agência Câmara de Notícias</em></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 19:42:13', '2026-02-02 19:42:13', '2026-02-02 19:42:13', 1, 1, 14);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (16, 'alcolumbre-defende-dialogo-e-repudio-ao-extremismo-na-abertura-do-ano-legislativo', 'Alcolumbre defende diálogo e repúdio ao extremismo na abertura do ano legislativo', '', '<!-- wp:paragraph -->
<p>Em discurso na solenidade de abertura do ano legislativo de 2026, o presidente do Congresso Nacional, senador Davi Alcolumbre, afirmou que o Parlamento deve atuar para não ampliar conflitos, mas ajudar a resolvê-los, evitando extremismos em um ano de eleições gerais.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Ao pedir “bom senso e paz” entre grupos ideológicos, instituições e poderes da República, Alcolumbre destacou o papel do Legislativo como espaço de mediação política. “O dissenso não pode se transformar em ódio, a discordância não pode jamais se transformar em violência. Não é fugir das tensões próprias da vida democrática, mas tratá-las com seriedade e sobretudo com maturidade”, declarou.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Justiça social e tributária</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>O senador reafirmou o compromisso do Congresso em melhorar de forma concreta a vida da população, citando como conquistas recentes a regulamentação da reforma tributária e a isenção do Imposto de Renda para quem ganha até R$ 5 mil por mês.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Para o presidente do Congresso, essas medidas demonstram a responsabilidade social do Parlamento. “Ao garantir esta isenção, o Congresso Nacional fez uma escolha clara: proteger quem vive do salário e cobrar um pouco mais de quem naturalmente pode mais. A justiça social também se constrói por meio do sistema tributário”, disse.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Defesa das prerrogativas</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Alcolumbre ressaltou ainda a importância histórica de 2026, ano em que a Câmara dos Deputados e o Senado Federal completam 200 anos de funcionamento, e defendeu a autonomia do Legislativo.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Ele pontuou que a busca pela paz não significa omissão na defesa das prerrogativas parlamentares, da autoridade do Congresso Nacional e do Estado de Direito. “Nosso desejo de paz não significa que tenhamos medo de luta. Nossa luta é e sempre será em defesa de todos os brasileiros. Desses valores e dessas batalhas nós jamais abriremos mão”, enfatizou.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">União e respeito</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Ao encerrar, o presidente do Congresso projetou um ano de trabalho voltado para a união do país, rejeitando a fragmentação social. Ele convocou os parlamentares a estarem à altura do bicentenário do Legislativo, priorizando o respeito recíproco. “Escolhemos o trabalho, escolhemos o respeito, escolhemos o diálogo. Escolhemos um Congresso Nacional firme na defesa de suas prerrogativas e consciente de que a política deve servir à união do povo brasileiro”, concluiu.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><em>Fonte: Agência Câmara de Notícias</em></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 19:50:07', '2026-02-02 19:50:07', '2026-02-02 19:50:07', 1, 1, 16);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (17, 'camara-aprova-medida-provisoria-que-cria-o-gas-do-povo', 'Câmara aprova medida provisória que cria o Gás do Povo', '', '<!-- wp:paragraph -->
<p>Os deputados aprovaram em votação no plenário a medida provisória que cria o programa Gás do Povo, uma das apostas eleitorais do presidente Luiz Inácio Lula da Silva para 2026. O texto ainda precisa de aprovação no Senado.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Proposta foi aprovada por 415 a 29 e duas abstenções. A medida provisória foi publicada pelo governo em 4 de setembro do ano passado e tem até 11 de fevereiro para ser aprovada nas duas Casas e não perder a validade. Ainda é necessário passar no Senado.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A medida provisória cria o Gás do Povo. O programa foi instituído originalmente pelo ex-presidente Jair Bolsonaro (PL). Agora, passa a se chamar Gás do Povo e teve sua operação modificada.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Auxílio gás do governo Bolsonaro foi criado como um benefício temporário. O programa fazia o pagamento a cada dois meses, para ajudar famílias de baixa renda a comprar o botijão, com valor variável conforme o preço médio do gás.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Vale-gás de Lula é uma política social permanente. O programa garante o pagamento regular equivalente a 100% do valor médio do botijão de 13 kg para as famílias do CadÚnico. Veja quem pode participar do programa e como pedir vale para recarregar o botijão.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Objetivo é chegar a 15 milhões de famílias. Quando instituído, o programa passou a valer para 10 capitais. Recentemente, incluiu as demais 17 capitais restantes.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><em>Com informações do Estadão</em></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 21:13:53', '2026-02-02 21:13:53', '2026-02-02 21:13:53', 1, 1, 22);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (18, 'lula-defende-fim-da-escala-de-trabalho-6x1', 'Lula defende fim da escala de trabalho 6x1', '', '<!-- wp:paragraph -->
<p>O presidente Luiz Inácio Lula da Silva destacou, na mensagem enviada ao Congresso Nacional, que vai trabalhar para o fim da escala de trabalho 6x1. De acordo com ele, o desafio é reduzir a jornada de trabalho sem redução de salário.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“O tempo é um dos bens mais preciosos para o ser humano. Não é justo que uma pessoa trabalhe duro toda a semana e tenha apenas um dia para descansar o corpo e a mente e curtir a família”, declarou o presidente.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Lula ainda mencionou a necessidade de regular o trabalho de quem atua por meio de aplicativos. “Dependem de defesa institucional do Estado brasileiro para mediar melhores condições de trabalho”, ressaltou.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Mais de uma proposta com esse objetivo foi apresentada tanto na Câmara quanto no Senado — elas divergem, contudo, em relação à quantidade de dias de folga. Atualmente, o modelo adotado prevê seis dias de trabalho e um de descanso.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">‘Prioridade absoluta’</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Após a cerimônia, o líder do governo no Congresso, senador Randolfe Rodrigues (PT-PB), ressaltou que é compromisso central do Planalto aprovar o fim da escala 6x1.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Segundo ele, a ideia é avançar os projetos que já tramitam no Congresso. “Nós queremos dialogar com os presidentes das casas que esse tema, o fim da escala 6 por 1, é prioridade ampla e absoluta de nosso governo”, destacou.</p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 22:22:06', '2026-02-02 22:22:06', '2026-02-02 22:22:06', 1, 1, 18);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (19, 'acusados-de-matar-empresario-erlan-oliveira-passam-por-audiencia-de-instrucao', 'Acusados de matar empresário Erlan Oliveira passam por audiência de instrução', 'Homicídio', '<!-- wp:paragraph -->
<p>A audiência de instrução e julgamento do caso Erlan Oliveira, empresário piauiense morto em junho de 2025, foi retomada no Fórum de Petrolina (PE) nesta segunda-feira (2).</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O julgamento, presidido pela juíza Elane Brandão Ribeiro (Vara do Tribunal do Júri), está previsto para durar três dias, com o objetivo de ouvir aproximadamente 25 testemunhas de defesa e acusação.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Na sessão de hoje, foram ouvidos um vereador de Ouricuri, um empresário de celulares e o motorista de aplicativo que transportou Erlan até o local do crime, no bairro José e Maria. Antes do recesso, um segurança do bar já havia prestado depoimento como testemunha ocular.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Um vídeo inédito circula nas redes sociais e foi mencionado como peça que pode alterar os rumos do caso. As imagens mostrariam Erlan sendo agredido por um homem (possivelmente um segurança) logo após desembarcar do veículo, antes da confusão generalizada que resultou em seu espancamento fatal.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Atualmente, seis pessoas estão no banco dos réus. A defesa questiona a ausência de certos laudos e vídeos no processo oficial.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Prisões</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Durante a investigação, seis pessoas foram presas pela morte do empresário, que foram: João Ítalo Barbosa, Iak Lima e José Lima F Júnior. Vitória Maria e Laiza Guimarães cumprem prisão domiciliar e Franklin Aquino responde ao processo em liberdade.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O inquérito da Polícia Civil revela que Erlan Oliveira foi agredido na madrugada de 20 de junho, quando ele deixou o Pátio de Eventos de Petrolina, onde participava dos festejos juninos.</p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 22:41:50', '2026-02-02 22:41:50', '2026-02-02 22:41:50', 1, 1, 19);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (20, 'vasco-empata-com-madureira-em-sao-januario', 'Vasco empata com Madureira em São Januário', 'Carioca', '<!-- wp:paragraph -->
<p>O Vasco em 0 a 0 com o Madureira nesta segunda-feira (2) em São Januário em partida válida pela penúltima rodada da 1ª fase do Campeonato Carioca.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Classificação</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>A equipe de Fernando Diniz chegou aos 8 pontos e, na 4ª posição do Grupo A, ainda não garantiu vaga nas quartas de final da Taça Guanabara. O time de Toninho Andrade, por sua vez, soma 7 pontos e é vice-líder do Grupo B — os quatro melhores de cada chave se classificam às quartas de final.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Agenda</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>O Madureira encara o Volta Redonda, enquanto o Vasco tem clássico contra o Botafogo na rodada final — antes disto, o time encara a Chapecoense, na quinta, pelo Brasileirão.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Puma perde pênalti</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Nuno Moreira foi derrubado dentro da área por Júlio César. O problema é que, na cobrança, Pumita Rodríguez parou em Neguete, que ainda conseguiu bloquear Brenner no rebote.</p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 22:59:19', '2026-02-02 22:59:19', '2026-02-02 22:59:19', 1, 1, 20);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (21, 'lula-envia-acordo-comercial-mercosul-ue-para-o-congresso-nacional', 'Lula envia acordo comercial Mercosul-UE para o Congresso Nacional', 'DOU', '<!-- wp:paragraph -->
<p>O presidente Luiz Inácio Lula da Silva oficializou nesta segunda-feira (2) o envio do acordo comercial entre Mercosul e União Europeia (UE) para o Congresso Nacional. O despacho foi publicado em edição extra do Diário Oficial da União (DOU).</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Os parlamentares brasileiros precisam aprovar o tratado para que ele possa entrar em vigor, o que deve ocorrer ao longo das próximas semanas em votações tanto na Câmara dos Deputados quanto no Senado Federal.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O acordo estabelece a maior zona de livre comércio do mundo, com mais de 720 milhões de habitantes. Ele foi assinado por representantes dos dois lados no último dia 17 de janeiro, em Assunção, no Paraguai.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Pelos termos do que foi aprovado, o tratado comercial prevê a eliminação de tarifas alfandegárias sobre a maior parte dos bens e serviços produzidos entre os dois blocos.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O Mercosul zerará tarifas sobre 91% dos bens europeus em até 15 anos. Já União Europeia eliminará tarifas sobre 95% dos bens do Mercosul em até 12 anos.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Apesar da assinatura formal entre os dois blocos, a internalização do acordo precisa ser feita pelos congressos nacionais de cada um dos países do Mercosul, bem como do Parlamento Europeu.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>No caso dos europeus, no entanto, o encaminhamento do acordo para análise do Tribunal de Justiça da União Europeia (TJUE), em decisão ocorrida há duas semanas, travou o texto e pode atrasar em até dois anos essa etapa final.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A expectativa do governo brasileiro é de que aprovação pelo Congresso Nacional ajude a pressionar o avanço do acordo por parte do Parlamento Europeu.</p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-02 23:02:44', '2026-02-02 23:02:44', '2026-02-02 23:02:44', 1, 1, 43);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (22, 'cartao-de-credito-e-aliado-no-planejamento-financeiro-para-2026', 'Cartão de crédito é aliado no planejamento financeiro para 2026', '', '<!-- wp:paragraph -->
<p>O planejamento financeiro é essencial para quem deseja mais organização e segurança em 2026. Nesse contexto, o cartão de crédito pode ser um importante aliado quando utilizado de forma consciente e responsável, permitindo uma melhor gestão dos gastos, definir metas e se programar para o futuro.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Ao concentrar as despesas no cartão, fica mais fácil acompanhar tudo pela fatura, facilitando o controle do orçamento mensal. O parcelamento também contribui para o planejamento, permitindo a realização de compras de forma equilibrada, sem comprometer a renda de uma só vez.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Com organização, é possível cortar gastos desnecessários, montar uma reserva de emergência e até guardar dinheiro para realizar grandes metas. O planejamento facilita a realização dos objetivos e melhora as decisões financeiras.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A gerente de marketing da Credi-Shop, Vaniela Alencar, reforça a importância da educação financeira. “O cartão de crédito é uma ferramenta que auxilia na organização financeira quando o cliente conhece seu limite, acompanha a fatura e utiliza o crédito de forma consciente, com foco em seus objetivos para 2026”, destaca.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O uso da tecnologia também facilita esse controle. Os cartões de crédito possuem aplicativos que auxiliam nessa tarefa. Por meio dessa plataforma, os consumidores podem acompanhar os gastos, consultar a fatura e o limite disponível, tudo de forma prática, o que contribui para uma administração mais eficiente.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Com organização e atenção aos gastos, o cartão de crédito pode ajudar a manter as finanças em dia e contribuir para um gerenciamento mais eficaz ao longo de todo o ano e menos preocupação com imprevistos.<br><br><em>Com informações da Ascom<br></em></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-03 07:58:06', '2026-02-03 07:58:06', '2026-02-03 07:58:06', 1, 1, 24);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (23, 'afya-parnaiba-tem-alta-aprovacao-nas-residencias-medicas-com-mais-de-60-nos-primeiros-lugares', 'Afya Parnaíba tem alta aprovação nas residências médicas, com mais de 60% nos primeiros lugares', '', '<!-- wp:paragraph -->
<p>A médica Brenda Cardoso, 24 anos, formada pela Afya Parnaíba, conquistou o primeiro lugar na residência em Ginecologia e Obstetrícia do Hospital Universitário da Universidade Federal do Maranhão (HU-UFMA). A aprovação simboliza um resultado mais amplo da instituição, que soma mais de 25 egressos aprovados em programas de residência médica em hospitais de diferentes estados brasileiros.<br></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A escolha da especialidade foi marcada por uma experiência pessoal vivida durante a graduação. Em dúvida entre a Ginecologia e a Otorrinolaringologia, Brenda acompanhava de perto o tratamento da menopausa de uma familiar.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p> “Ver a melhora da qualidade de vida dela e a resolutividade do cuidado gineco-endócrino me fez ter certeza de que era isso que eu queria fazer na vida”, conta.<br></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Segundo a médica, o contato precoce com pacientes e a metodologia ativa adotada ao longo do curso foram decisivos para o resultado.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p> “A consulta sob supervisão se torna rotina ainda durante a graduação, o que faz muita diferença na vida médica”, afirma. Natural de São Paulo, mas criada em Piripiri (PI), Brenda destaca ainda a estrutura e o corpo docente da instituição.<br></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Outro egresso que ilustra o desempenho da formação médica da Afya Parnaíba é Lucas Soares, 25 anos, natural de Teresina. Ele foi aprovado em três programas de residência em Clínica Médica, em Manaus (AM), Rio Grande (RS) e São Paulo, e vai assumir a vaga no Hospital Municipal Alípio Corrêa Neto, na capital paulista. Lucas destaca o acompanhamento acadêmico como diferencial desde os primeiros períodos. </p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“O teste de progresso permitia acompanhar nossa evolução ao longo do curso, já que a prova era a mesma para todos os períodos. Além disso, sempre tivemos professores excelentes”, relata.<br></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A vivência prática também foi determinante. “No ciclo clínico e no internato, passamos por ambulatórios de várias especialidades, com professores realmente dispostos a ensinar", avalia.</p>
<!-- /wp:paragraph -->

<!-- wp:image {"id":387692,"sizeSlug":"large","linkDestination":"none"} -->
<figure class="wp-block-image size-large"><img src="https://diario.dopovo.com.br/wp-content/uploads/2026/02/Afya-Parnaiba2-1024x576.jpg" alt="" class="wp-image-387692"/><figcaption class="wp-element-caption"><em>Foto: Divulgação</em></figcaption></figure>
<!-- /wp:image -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Formação prática e inserção no SUS</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Além dos destaques individuais, a Afya Parnaíba inicia 2026 com aprovações em especialidades reconhecidas pela alta concorrência, como Anestesiologia, Cirurgia Geral, Pediatria, Otorrinolaringologia e Ginecologia e Obstetrícia, com cerca de 60% dos egressos aprovados nos primeiros lugares e casos de estudantes aprovados ainda durante a graduação.<br></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>De acordo com a coordenadora acadêmica da instituição, Tereza Garcês, os resultados refletem um projeto pedagógico consolidado, baseado nas Diretrizes Curriculares Nacionais do curso medicina, em metodologias ativas de ensino-aprendizagem e uso de tecnologias educacionais, acompanhamento contínuo do estudante, práticas em cenários de simulação de baixa, média e alta fidelidade e a inserção precoce nos cenários de prática, principalmente no SUS. A Afya Parnaíba mantém convênios com a rede pública e conta com uma Clínica Acadêmica contratualizada com o SUS, que realiza mais de 12 mil atendimentos por ano.<br></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Com 10 anos de atuação, conceito institucional nota 5 no MEC e CPC 4 no curso de Medicina, a Afya Parnaíba reforça, por meio dos resultados de seus egressos, o compromisso com a formação de médicos competentes, humanizados e preparados para atuar nas diversas realidades do sistema de saúde.</p>
<!-- /wp:paragraph -->

<!-- wp:image {"id":387693,"sizeSlug":"large","linkDestination":"none"} -->
<figure class="wp-block-image size-large"><img src="https://diario.dopovo.com.br/wp-content/uploads/2026/02/Afya-Parnaiba3-1024x576.jpg" alt="" class="wp-image-387693"/><figcaption class="wp-element-caption"><em>Foto: Divulgação</em></figcaption></figure>
<!-- /wp:image -->

<!-- wp:paragraph -->
<p><em>Com informações da Ascom<br></em></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-03 08:13:07', '2026-02-03 08:13:07', '2026-02-03 08:13:07', 1, 1, 27);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (24, 'policlinica-retoma-atendimentos-medicos-gratuitos-em-varias-especialidades', 'Policlínica retoma atendimentos médicos gratuitos em várias especialidades', '', '<!-- wp:paragraph -->
<p>Com o início das aulas, a policlínica (clínica escola) do Instituto de Educação Médica (IDOMED), vinculada ao Unifacid Wyden, retomou uma diversidade de atendimentos médicos gratuitos com foco na população do Piauí e estados vizinhos. O objetivo da oferta dos serviços é garantir mais qualidade na saúde, acesso democrático e aperfeiçoamento do conhecimento de docentes e discentes. Somente em 2025, a unidade atendeu 9.066 pessoas gratuitamente. Para este ano, a expectativa é ampliar esse cenário, uma vez que isso significa mais pessoas sendo cuidadas de forma segura e eficiente.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Para garantir o atendimento, é fundamental agendar suas consultas médicas por meio do Sistema Único de Saúde (SUS), que direciona o paciente à unidade, que fica localizada no bairro Horto Florestal, em Teresina, com funcionamento das 7h às 17h30. Segundo Leonardo Rodrigues, diretor do IDOMED Piauí, os investimentos em capacitação e estrutura são fundamentais para possibilitar às pessoas atendimentos ainda mais humanizados e respeitosos.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p> “Nossa clínica tem potencial para consulta, exames e procedimentos em inúmeras especialidades. Quando o paciente vem à nossa policlínica, ele pode iniciar ou dar seguimento a seus tratamentos com um quadro de profissionais e estudantes altamente capacitados”, endossa.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Na policlínica, a população também pode buscar por atendimentos na área de psicologia, odontologia (infantil e adulta), enfermagem e fisioterapia. Luciano Rocha, reitor do Unifacid Wyden, reitera que manter um leque diversificado de especialidades contribui com a sociedade atual.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p> “Apostamos em serviços humanizados, respeitosos e em várias áreas da saúde, pensando exatamente em tudo naquilo que é imprescindível para a população em termos de cuidados médicos. É um trabalho coletivo, que tem gerado bons resultados. Para este ano, manteremos a confiança e o suporte a todos que nos procuram”, enfatiza.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Em 2025, a policlínica realizou mais de 9 mil atendimentos</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>No ano de 2025, a policlínica atendeu 9.066 pessoas gratuitamente com serviços em diversas especialidades médicas. Em segmentos, as áreas de ginecologia (1064), pediatria (876), reumatologia (648) e cardiologia (618) foram as mais procuradas pela população. Dessa forma, o levantamento mostra a importância de iniciativas na área da saúde que promovam acesso mais igualitário e, na mesma medida, reforça que a unidade conta com ampla capacidade de atender mais pessoas.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Especialidades disponíveis na Policlínica</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Ginecologia; reumatologia; cardiologia; angiologia; cirurgia de cabeça e pescoço; clínica geral; endocrinologia; gastroenterologista; geriatria; mastologia; nefrologia; neurologia; oftalmologia; ortopedia; otorrinolaringologia; pneumologia; pediatria; pequenas cirurgias; proctologia; psiquiatria; urologia; citologia; colposcopia e histopatológico. Além disso, podem buscar atendimentos em psicologia, odontologia, enfermagem e fisioterapia.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Para ter mais informações, é possível entrar em contato por meio do telefone: 86 3216-7928.<br><br><em>Com informações da Ascom<br></em></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-03 08:17:37', '2026-02-03 08:17:37', '2026-02-03 08:17:37', 1, 1, 28);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (25, 'draco-deflagra-operacao-e-cumpre-15-mandados-de-prisao-em-corrente', 'Draco deflagra operação e cumpre 15 mandados de prisão em Corrente', 'Crime organizado', '<!-- wp:paragraph -->
<p>A Polícia Civil do Piauí, por meio do Departamento de Repressão às Ações Criminosas Organizadas (DRACO), deflagrou nesta terça-feira (3) operação na cidade de Corrente, no extremo sul do Piauí, com o objetivo de cumprir 15 mandados judiciais de prisão e de busca e apreensão, além de intensificar o combate ao tráfico de drogas e à atuação de organizações criminosas na região.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>De acordo com o delegado Charles Pessoa, a ação é resultado de um trabalho investigativo contínuo.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“Esses alvos já vinham sendo monitorados há algum tempo. Com o apoio da inteligência da Secretaria de Segurança Pública, da Polícia Civil e da Delegacia Seccional de Corrente, foi possível reunir elementos suficientes para o cumprimento dos mandados e o avanço das investigações”, pontuou.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Participaram da operação a Delegacia Seccional de Corrente, em conjunto com o Departamento de Repressão às Ações Criminosas Organizadas (DRACO), Diretoria de Polícia do Interior (DPI), Inteligência da Secretaria de Segurança Pública, Força Estadual Integrada de Segurança Pública (FEISP) e Polícia Militar do Piauí, por meio do Batalhão de Operações Especiais (BOPE), Batalhão Especial de Policiamento do Interior (BEPI) e Força Tática.</p>
<!-- /wp:paragraph -->

<!-- wp:image {"id":387701,"sizeSlug":"large","linkDestination":"none"} -->
<figure class="wp-block-image size-large"><img src="https://diario.dopovo.com.br/wp-content/uploads/2026/02/Draco-drogas-operacao-1024x576.jpg" alt="" class="wp-image-387701"/><figcaption class="wp-element-caption"><em>Drogas apreendidas pelo Draco em operação - Foto: Divulgação</em></figcaption></figure>
<!-- /wp:image -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-03 09:50:32', '2026-02-03 09:50:32', '2026-02-03 09:50:32', 1, 1, 30);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (26, 'rafael-fonteles-celebra-aprovacao-de-5-mil-alunos-no-sisu', 'Rafael Fonteles celebra aprovação de 5 mil alunos no Sisu', 'Educação', '<!-- wp:paragraph -->
<p>O governador Rafael Fonteles recebeu nesta terça-feira (2), no Palácio de Karnak. estudantes de escolas da rede estadual aprovados no Sistema de Seleção Unificada (Sisu) 2026. O grupo representou os mais de 5 mil alunos Seduc aprovados na primeira chamada do certame.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“Aqui são alunos do terceiro ano do Ensino Médio da Escola Pública do Piauí, aprovados em Medicina, Direito, Engenharia Elétrica, Ciência da Computação, Matemática e muito mais. Fico muito feliz de ver esses jovens acreditando na escola pública junto com as suas famílias e realizando esse sonho de entrar na universidade pública”, pontuou o gestor.</p>
<!-- /wp:paragraph -->

<!-- wp:image {"id":387705,"sizeSlug":"large","linkDestination":"none"} -->
<figure class="wp-block-image size-large"><img src="https://diario.dopovo.com.br/wp-content/uploads/2026/02/Rafael-Fonteles-aluno-aprovado-Sisu-2026--1024x683.jpg" alt="" class="wp-image-387705"/><figcaption class="wp-element-caption"><em>Governador Rafael Fonteles reunido com estudantes aprovados no Sisu - Foto: Gabriel Paulino</em></figcaption></figure>
<!-- /wp:image -->

<!-- wp:paragraph -->
<p>O secretário da Educação, Rodrigo Torres, destacou que os resultados refletem diretamente esse investimento estrutural.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“O melhor resultado da história da Seduc”, com mais de 5 mil aprovações, incluindo aumento expressivo em cursos de alta concorrência, como medicina, que teve o dobro de aprovados em relação ao ano anterior. “O modelo de tempo integral aliado ao ensino técnico e a disciplinas inovadoras tem funcionado e já começa a mostrar resultados concretos”, considerou Torres.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Para o ex-secretário da Educação, Washington Bandeira, o resultado histórico confirma que o tempo integral com formação profissional, esporte, cultura e preparação intensiva para o Enem se tornou a principal bandeira da educação pública do Piauí.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“Tivemos aí o Pré-Enem com inúmeras revisões, o Canal Educação com aplicativo com correção de redação por inteligência artificial, videoaulas, quizzes, simulados. Eles treinaram muito através do canal educação e o resultado veio”, ressaltou.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Entre os estudantes recebidos pelo governador estava Willian Rafael, 18, aluno do Ceti Premen Norte, aprovado em primeiro lugar no curso de Engenharia Elétrica da Universidade Estadual do Piauí. Participante do primeiro Seduckathon, hoje programa Do Piauí para o Mundo, ele atribuiu o desempenho ao acompanhamento dos professores.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>“Sempre nos incentivavam e reforçavam os conteúdos focados no Enem, houve um grande esforço para nos fazer chegar ao topo”, afirmou.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-03 11:20:35', '2026-02-03 11:20:35', '2026-02-03 11:20:35', 1, 1, 32);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (27, 'prf-apreende-adolescente-de-16-anos-transportando-34kg-de-maconha-em-teresina', 'PRF apreende adolescente de 16 anos transportando 34kg de maconha em Teresina', 'Entorpecente', '<!-- wp:paragraph -->
<p><br>A Polícia Rodoviária Federal (PRF) apreendeu nesta segunda-feira (2) uma adolescente de 16 anos transportando 33,97 quilos de maconha em um ônibus interestadual na BR-343, em Teresina. De acordo com a Polícia Rodoviária Federal (PRF), o veículo seguia viagem com destino a Fortaleza, no Ceará.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>A apreensão ocorreu no quilômetro 360 da rodovia, durante uma abordagem de rotina realizada pelos agentes. A droga estava armazenada em duas malas localizadas no bagageiro do ônibus.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Segundo a PRF, a jovem relatou que havia recebido as malas em São Paulo e que faria o transporte até o Ceará. Ela afirmou ainda que receberia R$ 2 mil pelo serviço e declarou não saber o conteúdo da bagagem.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Por se tratar de menor de idade, o nome e a imagem da adolescente não foram divulgados. Após a apreensão, a jovem e o material ilícito foram encaminhados à Central de Flagrantes de Teresina para a adoção dos procedimentos legais cabíveis.<br><br></p>
<!-- /wp:paragraph -->', '', 'published', '2026-02-03 12:29:26', '2026-02-03 12:29:26', '2026-02-03 12:29:26', 1, 1, 33);
INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (28, 'silvio-mendes-destaca-equilibrio-financeiro-na-abertura-do-ano-legislativo', 'Silvio Mendes destaca equilíbrio financeiro na abertura do ano legislativo', 'Câmara Municipal de Teresina', '<!-- wp:paragraph -->
<p>O prefeito de Teresina, Silvio Mendes, realizou nesta terça-feira (3) a leitura da mensagem anual do Executivo. O ato solene foi realizado na sessão inaugural do ano legislativo de 2026, no Plenário da Câmara Municipal de Teresina. O gestor destacou o equilíbrio financeiro e traçou metas para 2026.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>‘’O equilíbrio fiscal, uma equipe equilibrada e experiente, esse é o ano de fazer mais do que o ano passado em todas as áreas, é o nosso desafio. Nós não temos conflito com a câmara. Eu espero que assim continue’’, disse Silvio.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Além disso, o gestor anunciou medidas relacionadas ao salário dos servidores municipais.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>‘’Alguns servidores ganham menos de um salário mínimo e não é justo, se o poder público não respeita, quem é que vai respeitar? Então nós vamos desfazer esse erro, todos os servidores da prefeitura vão ganhar pelo menos um salário mínimo, sem penduricalho, salário cheio. Segundo: ao longo do tempo, foi se fazendo algumas diferenças de alguns servidores onde, na mesma categoria, alguns de secretarias diferentes ganhavam salários diferentes. Agora, todos vão ganhar igual. Terceiro: o 13°&nbsp;vai ser pago durante todo o ano, a partir do aniversário do servidor. E quarto, o reajuste, a partir da data-base, que vai ser de 5.35%, porque é assim que a lei determina. Esse ano a gente pode cumprir a lei.’’, concluiu o prefeito.&nbsp;</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O vice-prefeito de Teresina, Jeová Alencar, destacou o esforço do prefeito Silvio Mendes em colocar a Prefeitura numa situação melhor que a encontrada.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>‘’O prefeito conseguiu um fato inédito, que é ter o equilíbrio financeiro. Com o equilíbrio financeiro você consegue fazer um planejamento para investimentos, que é o que a cidade precisa. O ano de 2025 foi muito difícil, mas acredito que com as medidas tomadas pelo prefeito Silvio Mendes e esse equilíbrio financeiro, a gente consegue fazer os investimentos e claro, que 2026 seja melhor para todos nós’’, afirmou.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>O presidente da Câmara de Vereadores, Enzo Samuel, frisou o bom relacionamento do Legislativo com o Executivo municipal.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>‘’O prefeito deixou uma mensagem muito importante, eu tinha concedido uma entrevista recentemente, falei que o ano passado foi um ano de equilíbrio fiscal e esse será um ano de investimentos, então o prefeito fez uma boa mensagem, anunciou reajuste de servidores e equiparação salarial. A gente espera manter essa boa relação em prol do trabalho pelo povo, que eu acho importante e é prioridade na gestão do prefeito Silvio Mendes e na minha aqui à frente da Câmara Municipal. Nosso cuidado é com a cidade’’, ponderou.</p>
<!-- /wp:paragraph -->

<!-- wp:image {"id":387712,"sizeSlug":"large","linkDestination":"none"} -->
<figure class="wp-block-image size-large"><img src="https://diario.dopovo.com.br/wp-content/uploads/2026/02/Silvio-Mendes-Jeova-Alencar-1024x683.jpg" alt="" class="wp-image-387712"/><figcaption class="wp-element-caption"><em>Abertura do ano legislativo na Câmara Municipal de Teresina - Foto: Jailson Soares</em></figcaption></figure>
<!-- /wp:image -->

<!-- wp:paragraph -->
<p></p>
