INSERT INTO posts (id, slug, title, hat, content, excerpt, status, published_at, created_at, updated_at, author_id, category_id, cover_media_id) VALUES (29, 'sine-disponibiliza-mais-de-150-vagas-de-emprego-no-piaui-nesta-terca-feira', 'Sine disponibiliza mais de 150 vagas de emprego no Piauí nesta terça-feira', 'Oportunidade', '<!-- wp:paragraph -->
<p>O Sistema Nacional de Emprego (Sine) divulgou, nesta terça-feira (3), mais de 150&nbsp; oportunidades de emprego em Teresina e em municípios do interior do Piauí. As vagas contemplam diferentes áreas de atuação, níveis de escolaridade e incluem ainda oportunidades destinadas exclusivamente a pessoas com deficiência (PCDs). As vagas podem ser alteradas ou preenchidas a qualquer momento.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Teresina</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Assistente de serviço de contabilidade (1 vaga) – Ensino médio completo, seis meses de experiência, registro ativo no Creci, veículo próprio e CNH categoria B.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Auxiliar de linha de produção (20 vagas) – Ensino fundamental completo e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Corretor de imóveis (1 vaga) – cursando negócios imobiliários, seis meses de experiência, Creci ativo e experiência em captação e vendas.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Costureiro de roupas – confecção em série (30 vagas) –Seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Criador de conteúdo digital (1 vaga) – Ensino superior ou tecnólogo em marketing digital e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Digitador (1 vaga) – Ensino médio completo, seis meses de experiência, conhecimento em Excel, Word e faturamento.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Gerente comercial (1 vaga) – Ensino superior em administração ou áreas afins e seis meses de experiência com CTPS, pacote office intermediário, conhecimento em metodologia kanbam e habilidade em gestão de conflito.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Instalador-reparador de linhas de comunicação de dados (8 vagas)&nbsp;– Ensino fundamental completo e experiência mínima de seis meses.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Instalador-reparador de linhas de comunicação de dados (5 vagas)&nbsp;– Ensino médio completo e experiência mínima de seis meses.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Jardineiro (3 vagas) – Ensino fundamental completo e experiência mínima de seis meses.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Mecânico de auto em geral (1 vaga) – Ensino médio completo e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Mecânico de manutenção de motocicletas (2 vagas) – Ensino médio completo e curso técnico, além de seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Motorista carreteiro (12 vagas) – Ensino médio completo e seis meses de experiência&nbsp;com CTPS, necessário certificados de direção defensiva, primeiros socorros, nr 06 e mopp averbado na CNH.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Motorista de caminhão basculante (5 vagas) – Ensino médio completo e seis meses de experiência&nbsp;com basculante, rodocaçamba, graneleiro e rodotrem.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Recepcionista atendente (1 vaga) – Ensino médio completo.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Representante comercial autônomo (3 vagas) – Ensino médio completo e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Supervisor de operações logísticas (2 vagas) – Ensino médio completo e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Técnico de contabilidade (1 vaga) – Ensino médio completo e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Técnico de manutenção eletrônica (2 vagas) – Curso técnico e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Técnico em manutenção de equipamentos de informática (2 vagas) – Ensino médio completo e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Técnico de suporte de TI (1 vaga) – Formação na área ou afins, seis meses de experiência com CTPS.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Tosador de animais domésticos (1 vaga) – Ensino médio completo e seis meses de experiência.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p><strong>Vagas exclusivas para pessoas com deficiência (PCDs) – Teresina:</strong></p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Assistente de vendas (1 vaga) – Ensino médio completo.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Auxiliar de limpeza (1 vaga) – Ensino fundamental completo.</p>
<!-- /wp:paragraph -->

<!-- wp:heading {"level":3} -->
<h3 class="wp-block-heading">Floriano</h3>
<!-- /wp:heading -->

<!-- wp:paragraph -->
<p>Ajudante de serralheiro (2 vagas) – Ensino fundamental completo.</p>
<!-- /wp:paragraph -->

<!-- wp:paragraph -->
<p>Auxiliar de limpeza (8 vagas) – Sem exigências.</p>
<!-- /wp:paragraph -->

